class TestGetConfigPath:
    """Tests for the get_config_path function."""

    def test_default_config_path(self, monkeypatch):
        """Test that default path is returned when no profile or env var is set."""
        monkeypatch.delenv("QAIHUB_CLIENT_INI", raising=False)

        path = api_utils.get_config_path(expanduser=False)
        assert path == "~/.qai_hub/client.ini"

    def test_config_path_with_profile(self, monkeypatch):
        """Test that profile-based path is returned when profile is specified."""
        monkeypatch.delenv("QAIHUB_CLIENT_INI", raising=False)

        path = api_utils.get_config_path(profile="my_profile", expanduser=False)
        assert path == "~/.qai_hub/my_profile.ini"

    def test_config_path_from_env_var(self, monkeypatch):
        """Test that environment variable takes precedence when no profile is specified."""
        monkeypatch.setenv("QAIHUB_CLIENT_INI", "/custom/path/config.ini")

        path = api_utils.get_config_path(expanduser=False)
        assert path == "/custom/path/config.ini"

    def test_profile_takes_precedence_over_env_var(self, monkeypatch):
        """Test that profile takes precedence over environment variable."""
        monkeypatch.setenv("QAIHUB_CLIENT_INI", "/custom/path/config.ini")

        path = api_utils.get_config_path(profile="my_profile", expanduser=False)
        assert path == "~/.qai_hub/my_profile.ini"


class TestLoadApiConfigFromFile:
    """Tests for loading API config from config files."""

    def test_load_valid_config_file(self, temp_dir):
        """Test loading a valid config file with all required fields."""

        config_file = temp_dir / "test_config.ini"
        config_file.write_text(
            """[api]
api_url = https://test_domain
web_url = https://test_domain
api_token = test_token_123
verbose = true
"""
        )

        config = api_utils.load_api_config_from_file(str(config_file))

        assert config.api_url == "https://test_domain"
        assert config.web_url == "https://test_domain"
        assert config.api_token == "test_token_123"
        assert config.default_project is None

    def test_load_config_file_with_default_project(self, temp_dir):
        """Test loading a config file that includes default_project."""

        config_file = temp_dir / "test_config.ini"
        config_file.write_text(
            """[api]
api_url = https://test_domain
web_url = https://test_domain
api_token = test_token_123
verbose = false
default_project = proj_abc123
"""
        )

        config = api_utils.load_api_config_from_file(str(config_file))

        assert config.api_token == "test_token_123"
        assert config.default_project == "proj_abc123"

    def test_load_config_file_missing_required_field(self, temp_dir):
        """Test that loading a config file with missing required fields raises an error."""

        config_file = temp_dir / "test_config.ini"
        config_file.write_text(
            """[api]
api_url = https://test_domain
web_url = https://test_domain
"""
        )

        with pytest.raises(public_rest_api.APIException):
            api_utils.load_api_config_from_file(str(config_file))

    def test_load_config_file_not_found(self):
        """Test that loading a non-existent config file raises FileNotFoundError."""
        with pytest.raises(FileNotFoundError):
            api_utils.load_api_config_from_file("/non/existent/path/config.ini")


class TestLoadApiConfigFromProfile:
    """Tests for loading API config from a named profile."""

    def test_load_config_from_profile(self, temp_dir, monkeypatch):
        """Test loading config using a profile name."""
        profile_dir = temp_dir / ".qai_hub"
        profile_dir.mkdir()
        profile_file = profile_dir / "test_profile.ini"
        profile_file.write_text(
            """[api]
api_url = https://test_domain
web_url = https://test_domain
api_token = profile_token_456
verbose = true
default_project = profile_proj
"""
        )

        def mock_expanduser(path):
            return str(path).replace("~", str(temp_dir))

