class TestResponseAsProtobuf404Handling:
    """Tests for response_as_protobuf handling of 404 responses."""

    def _make_response(self, status_code, text="", content_type="application/json"):
        resp = MagicMock()
        resp.status_code = status_code
        resp.text = text
        resp.url = "http://test_domain/api/v1/projects/xyz/models/"
        resp.headers = {"Content-Type": content_type}
        resp.content = b""
        return resp

    def test_404_with_obj_id_uses_existing_message(self):
        """Test that 404 with obj_id still produces the existing ID-based message."""
        resp = self._make_response(404, text='{"detail": "Not found."}')
        with pytest.raises(
            public_rest_api.APIException, match="ID 'job123' could not be found"
        ):
            api_utils.response_as_protobuf(resp, api_pb.Job, obj_id="job123")

    def test_404_without_obj_id_captures_response_text(self):
        """Test that 404 without obj_id captures response.text in the exception."""
        detail = "A completely made-up error detail message."
        resp = self._make_response(404, text=f'{{"detail": "{detail}"}}')
        with pytest.raises(
            public_rest_api.APIException, match="completely made-up"
        ) as exc_info:
            api_utils.response_as_protobuf(resp, api_pb.CreateUpdateResponse)
        assert exc_info.value.status_code == 404

    def test_404_without_obj_id_empty_body_falls_back(self):
        """Test that 404 with empty response body falls back to auto-generated message."""
        resp = self._make_response(404, text="")
        with pytest.raises(
            public_rest_api.APIException, match="status code 404"
        ) as exc_info:
            api_utils.response_as_protobuf(resp, api_pb.CreateUpdateResponse)
        assert exc_info.value.status_code == 404


class TestRaiseIfHubUserError404Handling:
    """Tests for _raise_if_hub_user_error extracting detail from 404 responses."""

    def _make_client(self):
        config = public_rest_api.ClientConfig(
            api_url="http://test_domain",
            web_url="http://test_domain",
            api_token="token",
        )
        return Client(config=config)

    def test_descriptive_project_404_is_surfaced(self):
        """Test that a descriptive 404 from the server is extracted and shown to the user."""
        client = self._make_client()
        detail = "Another completely made-up error detail message."
        body = f'{{"detail": "{detail}"}}'

        def raise_404(cfg):
            raise public_rest_api.APIException(
                body,
                status_code=404,
                url="http://test_domain/api/v1/projects/xyz/models/",
            )

        with pytest.raises(
            UserError, match="Another completely made-up error detail message."
        ):
            client._api_call(raise_404)

    def test_generic_404_is_surfaced(self):
        """Test that a generic 404 body is surfaced as-is."""
        client = self._make_client()

        def raise_404(cfg):
            raise public_rest_api.APIException(
                '{"detail": "Not found."}',
                status_code=404,
                url="http://test_domain/api/v1/jobs/",
            )

        with pytest.raises(UserError, match="Not found."):
            client._api_call(raise_404)

    def test_non_json_404_is_passed_through(self):
        """Test that a non-JSON 404 body is passed through without crashing."""
        client = self._make_client()

        def raise_404(cfg):
            raise public_rest_api.APIException(
                "Not Found", status_code=404, url="http://test_domain/api/v1/models/"
            )

        with pytest.raises(UserError, match="Not Found"):
            client._api_call(raise_404)

    def test_404_with_no_message_falls_back(self):
        """Test that a 404 with no message falls back to auto-generated text."""
        client = self._make_client()

        def raise_404(cfg):
            raise public_rest_api.APIException(
                "", status_code=404, url="http://test_domain/api/v1/models/"
            )

        with pytest.raises(UserError, match="status code 404"):
            client._api_call(raise_404)


class TestModelProducerLazyLoading:
    def test_get_models_does_not_fetch_producer(self, client_config_no_default_project):
        client = Client(config=client_config_no_default_project)

        model_pb = api_pb.Model(
            model_id="fake_model_id",
            name="fake_model",
            producer_id="fake_job_id",
        )
        model_list_pb = api_pb.ModelList()
        model_list_pb.models.append(model_pb)

        with (
            mock.patch.object(client, "_api_call", return_value=model_list_pb),
            mock.patch.object(client, "get_job") as mock_get_job,
        ):
            models = client.get_models(limit=1)
            assert len(models) == 1
            mock_get_job.assert_not_called()

    def test_get_producer(self, client_config_no_default_project):
        client = Client(config=client_config_no_default_project)

        model_pb = api_pb.Model(
            model_id="fake_model_id",
            name="fake_model",
            producer_id="fake_job_id",
        )
        model_list_pb = api_pb.ModelList()
        model_list_pb.models.append(model_pb)

        fake_job = MagicMock()
        fake_job.job_id = "fake_job_id"

        with (
            mock.patch.object(client, "_api_call", return_value=model_list_pb),
            mock.patch.object(client, "get_job", return_value=fake_job) as mock_get_job,
        ):
            models = client.get_models(limit=1)

            # .get_producer() fetches on first call, caches on subsequent calls
            assert models[0].get_producer() is fake_job
            assert models[0].get_producer() is fake_job
            mock_get_job.assert_called_once_with("fake_job_id")

    def test_producer_property_is_deprecated(
        self, client_config_no_default_project, capsys
    ):
        client = Client(config=client_config_no_default_project)

        model_pb = api_pb.Model(
            model_id="fake_model_id",
            name="fake_model",
            producer_id="fake_job_id",
        )
        model_list_pb = api_pb.ModelList()
        model_list_pb.models.append(model_pb)

        fake_job = MagicMock()
        fake_job.job_id = "fake_job_id"

        with (
            mock.patch.object(client, "_api_call", return_value=model_list_pb),
            mock.patch.object(client, "get_job", return_value=fake_job),
        ):
            models = client.get_models(limit=1)
            assert models[0].producer is fake_job

        captured = capsys.readouterr()
        assert "Model.producer" in captured.out
        assert "deprecated" in captured.out

    def test_producer_is_none_when_no_producer_id(
        self, client_config_no_default_project
    ):
        client = Client(config=client_config_no_default_project)

        model_pb = api_pb.Model(model_id="fake_model_id", name="fake_model")
        model_list_pb = api_pb.ModelList()
